args <- commandArgs(trailingOnly = TRUE); value <- function(flag) { i <- match(flag, args); if (is.na(i) || i == length(args)) NULL else args[i + 1L] }; id <- value("--run-id"); path <- value("--run-directory"); if (is.null(id) || is.null(path) || !"--confirm" %in% args) stop("--run-id, --run-directory, and --confirm are required.", call. = FALSE); lock <- file.path(path, ".execution.lock"); if (!dir.exists(lock)) stop("No lock exists: ", lock, call. = FALSE); owner_lines <- readLines(file.path(lock, "owner"), warn = FALSE); cat(paste(owner_lines, collapse = "\n"), "\n"); pid <- sub("^pid=", "", grep("^pid=", owner_lines, value = TRUE)); active <- FALSE; if (.Platform$OS.type == "windows" && nzchar(pid)) { tasks <- system("tasklist /FO CSV /NH", intern = TRUE); active <- any(grepl(paste0('"', pid, '"'), tasks, fixed = TRUE)) }; if (active) stop("Refusing to clear a lock owned by an apparently active local process.", call. = FALSE); unlink(lock, recursive = TRUE, force = TRUE); cat("Cleared lock for ", id, "\n", sep = "")
